using System;
using System.Collections;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.SceneManagement;

[Serializable] public sealed class GridShiftLifeState {
 public float health=100,food=85,energy=90,hygiene=90,comfort=80;
 public int ingredients=4,meals=1,pendingIngredients,pendingMeals;
 public double groceriesDue=-1;public bool dead,tvOn;public string[] openFurniture=Array.Empty<string>();public string[] lightOnRooms=Array.Empty<string>(),lightOffRooms=Array.Empty<string>();
}
// One state per active save, owned by the existing DeliveryManager.
public sealed class GridShiftLife:MonoBehaviour {
 public static GridShiftLife Instance{get;private set;}public GridShiftLifeState State{get;private set;}=new GridShiftLifeState();
 public bool Acting{get;private set;}public bool Dead=>State.dead;DeliveryManager manager;GridShiftHomeRoutineFX routineFx;Transform activeStation;float warningAt;public string Activity{get;private set;}
 void Awake(){Instance=this;manager=GetComponent<DeliveryManager>();var hud=new GameObject("GridShift needs bars");hud.transform.SetParent(transform,false);hud.AddComponent<GridShiftLifeHUD>();}
 void OnDestroy(){if(routineFx!=null)routineFx.Dispose();if(Instance==this)Instance=null;}
 static float Safe(float v,float fallback)=>float.IsNaN(v)||float.IsInfinity(v)?fallback:Mathf.Clamp(v,0,100);
 public void Restore(GridShiftLifeState value){State=value==null?new GridShiftLifeState():JsonUtility.FromJson<GridShiftLifeState>(JsonUtility.ToJson(value));State.health=Safe(State.health,100);State.food=Safe(State.food,85);State.energy=Safe(State.energy,90);State.hygiene=Safe(State.hygiene,90);State.comfort=Safe(State.comfort,80);State.ingredients=Mathf.Clamp(State.ingredients,0,100);State.meals=Mathf.Clamp(State.meals,0,100);State.pendingIngredients=Mathf.Clamp(State.pendingIngredients,0,100);State.pendingMeals=Mathf.Clamp(State.pendingMeals,0,100);if(double.IsNaN(State.groceriesDue)||double.IsInfinity(State.groceriesDue))State.groceriesDue=-1;State.openFurniture=State.openFurniture??Array.Empty<string>();State.lightOnRooms=State.lightOnRooms??Array.Empty<string>();State.lightOffRooms=State.lightOffRooms??Array.Empty<string>();}
 public GridShiftLifeState Capture()=>JsonUtility.FromJson<GridShiftLifeState>(JsonUtility.ToJson(State));
 void Update(){if(manager==null||manager.Restoring||!manager.Company.Ready||Dead||WorldSession.Instance==null||WorldSession.Instance.Busy||Time.timeScale<=0)return;if(!Acting)AdvanceHours(Time.deltaTime/WorldSession.Instance.SecondsPerDay*24);DeliverGroceries();if((State.food<15||State.energy<15||State.hygiene<15)&&Time.time>warningAt){warningAt=Time.time+90;manager.Notify(State.food<15?"Você está com muita fome. Coma algo antes de perder vida.":State.energy<15?"Você precisa dormir. Vá para sua cama.":"Você precisa tomar banho. Os cidadãos estão percebendo.");}}
 public void AdvanceHours(float hours){if(Dead||hours<=0)return;hours=Mathf.Min(hours,24);float starvingHours=Mathf.Max(0,hours-State.food/4);State.food=Mathf.Max(0,State.food-hours*4);State.energy=Mathf.Max(0,State.energy-hours*5);State.hygiene=Mathf.Max(0,State.hygiene-hours*3);State.comfort=Mathf.Max(0,State.comfort-hours*2);if(starvingHours>0)Damage(starvingHours*12,"fome");}
 public void DeliverGroceries(){if(Dead||State.groceriesDue<0||WorldSession.Instance==null||WorldSession.Instance.CalendarDays<State.groceriesDue)return;State.ingredients=Mathf.Min(100,State.ingredients+State.pendingIngredients);State.meals=Mathf.Min(100,State.meals+State.pendingMeals);State.pendingIngredients=State.pendingMeals=0;State.groceriesDue=-1;manager.Notify("Suas compras chegaram e foram guardadas na geladeira.");Changed();}
 public bool BuyFood(bool ready){if(Dead||State.groceriesDue>=0){manager.Notify("Aguarde a entrega das compras em andamento.");return false;}int amount=ready?3:6;if(State.ingredients+State.pendingIngredients>94||State.meals+State.pendingMeals>97)return false;float price=ready?24:18;if(!manager.TryChangeMoney(-price,"groceries:"+Guid.NewGuid().ToString("N"),"Casa",ready?"Compra de três refeições":"Compra de seis ingredientes"))return false;State.pendingIngredients=ready?0:amount;State.pendingMeals=ready?amount:0;State.groceriesDue=WorldSession.Instance.CalendarDays+2.0/24;Changed();manager.Notify("Compra confirmada. Entrega na geladeira em 2 horas do jogo.");return true;}
 public string DeliveryText=>State.groceriesDue<0?"Sem entrega pendente.":"Entrega em "+Mathf.Max(0,(float)((State.groceriesDue-(WorldSession.Instance?.CalendarDays??0))*24)).ToString("0.0")+" h do jogo. Ingredientes: "+State.pendingIngredients+" · refeições: "+State.pendingMeals;
 public bool Use(string kind,PlayerMovement player,Transform station=null){if(Dead||Acting||player==null)return false;activeStation=station;if(kind=="wardrobe"){GridShiftCharacterEditor.Open(GridShiftCharacter.Current,d=>{GridShiftCharacter.Commit(d);manager.GetComponent<DeliveryPersistence>().Save();});return true;}if(kind=="fridge"){OpenFridge(player);return true;}if(kind=="eat"&&State.meals<1){manager.Notify("Não há refeição pronta na geladeira.");return false;}if(kind=="cook"&&State.ingredients<2){manager.Notify("São necessários 2 ingredientes. Compre no tablet → Compras.");return false;}StartCoroutine(Routine(kind,player));return true;}
 public void OpenFridge(PlayerMovement player){var ui=GridShiftCampaignUI.Instance;ui.Open("SUA GELADEIRA","Ingredientes: "+State.ingredients+"\nRefeições prontas: "+State.meals+"\n"+DeliveryText+"\nAs compras são finitas. Cozinhar consome dois ingredientes.");ui.Option("Comer uma refeição (+45 alimentação)",()=>{if(State.meals<=0){manager.Notify("Não há refeições prontas. Cozinhe ou compre no tablet.");return;}ui.Close();Use("eat",player,activeStation);});ui.Option("Fechar geladeira",ui.Close);}
 IEnumerator Routine(string kind,PlayerMovement player){if(kind=="relax")UnityEngine.Object.FindFirstObjectByType<GridShiftHomeTV>()?.SetOn(true);Acting=true;Activity=kind=="sleep"?"Dormindo · 8 horas":kind=="shower"?"Tomando banho":kind=="cook"?"Preparando refeição":kind=="toilet"?"Usando banheiro":kind=="wash"?"Lavando as mãos":kind=="eat"?"Comendo uma refeição":"Descansando / entretenimento";bool old=player.ControlsBlocked;player.BlockControls(true);routineFx=player.gameObject.AddComponent<GridShiftHomeRoutineFX>();routineFx.Begin(kind,activeStation,kind=="sleep"?7:kind=="eat"?3:5);if(kind=="sleep")yield return new WaitForSeconds(1.5f);if(kind=="sleep"&&FadeManager.Instance!=null)yield return FadeManager.Instance.FadeOut();if(kind=="eat"){State.meals--;Changed();}if(kind=="cook"){State.ingredients-=2;Changed();}yield return new WaitForSeconds(kind=="sleep"?6:kind=="shower"?4:kind=="eat"?3:5);if(!Dead){float hours=kind=="sleep"?8:kind=="shower"?.25f:kind=="cook"?.5f:kind=="toilet"?.1f:kind=="wash"?.05f:kind=="eat"?.25f:1;AdvanceHours(hours);WorldSession.Instance?.AdvanceHours(hours);DeliverGroceries();if(!Dead){if(kind=="sleep"){State.energy=100;State.health=Mathf.Min(100,State.health+10);}else if(kind=="shower")State.hygiene=100;else if(kind=="cook")State.meals++;else if(kind=="eat")State.food=Mathf.Min(100,State.food+45);else if(kind=="toilet"){State.comfort=Mathf.Min(100,State.comfort+15);State.hygiene=Mathf.Max(0,State.hygiene-5);}else if(kind=="wash")State.hygiene=Mathf.Min(100,State.hygiene+12);else State.comfort=Mathf.Min(100,State.comfort+45);Changed();manager.Notify(kind=="cook"?"Refeição pronta na geladeira.":"Rotina concluída: "+Activity);}}if(routineFx!=null)routineFx.Dispose();routineFx=null;if(kind=="sleep"&&FadeManager.Instance!=null)yield return FadeManager.Instance.FadeIn();Acting=false;Activity=null;if(player!=null&&!Dead)player.BlockControls(old);}
 public void Damage(float amount,string reason){if(Dead||manager==null||manager.Restoring||amount<=0)return;State.health=Mathf.Max(0,State.health-amount);if(State.health<=0){State.dead=true;StartCoroutine(Death(reason));}else Changed();}
 IEnumerator Death(string reason){GridShiftOperationsUI.Instance?.Close();GridShiftCampaignUI.Instance?.Close();foreach(var p in UnityEngine.Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None))p.BlockControls(true);string path=DeliverySaveStore.PathName;bool deleted=false;string error=null;if(string.IsNullOrEmpty(DeliverySaveStore.OverridePath)&&GridShiftProfiles.LoggedIn&&GridShiftProfiles.ActiveSlot>0)deleted=GridShiftProfiles.Delete(GridShiftProfiles.ActiveSlot,true,out error);else if(!string.IsNullOrEmpty(DeliverySaveStore.OverridePath)){try{foreach(var suffix in new[]{"",".bak",".tmp",".png"})if(File.Exists(path+suffix))File.Delete(path+suffix);deleted=true;}catch(Exception e){error=e.Message;}}DeliverySaveStore.Pending=null;DeliverySaveStore.StartFresh=false;yield return null;var ui=GridShiftCampaignUI.Instance;ui.Open("FIM DA VIDA · "+GridShiftCharacter.PlayerName,"Causa: "+reason+".\n"+(deleted?"O save desta partida e sua cópia de segurança foram apagados. Os outros slots foram preservados.":"A partida foi encerrada. Falha ao excluir o arquivo: "+error));ui.Option("Voltar ao menu",()=>{ui.Close();Time.timeScale=1;SceneManager.LoadScene("MainMenu");});}
 public string CitizenComment(){if(State.hygiene<20)return UnityEngine.Random.value<.5f?"Você está precisando de um banho. O cheiro está forte!":"Nada pessoal, mas passa em casa e toma um banho, por favor.";if(State.energy<20)return UnityEngine.Random.value<.5f?"Vai dormir! Essas olheiras estão entregando seu cansaço.":"Você parece esgotado. Sua cama está te esperando.";if(State.food<15)return "Você parece sem energia. Já comeu alguma coisa hoje?";return null;}
 public void Changed(){manager.Changed();manager.GetComponent<DeliveryPersistence>()?.RequestSave();}
}
